  $sections$[{"type":"header","variant":"clasico"},{"type":"hero","variant":"fondo","titulo":"La piel también se escribe","descripcion":"","imagenFiltro":"grayscale(0.45) contrast(1.15) brightness(0.75)","botones":{"primary":{"label":"Reservar mi turno"},"secondary":{"label":"Ver flash disponible"}}},{"type":"marquee","bgColor":"#9e2b25","separador":"✦","velocidad":22,"mensajes":[{"id":"tick-0","texto":"Blackwork"},{"id":"tick-1","texto":"Fineline"},{"id":"tick-2","texto":"Tradicional"},{"id":"tick-3","texto":"Realismo"},{"id":"tick-4","texto":"Cover-up"},{"id":"tick-5","texto":"Lettering"},{"id":"tick-6","texto":"Botánico"}]},{"type":"productos","variant":"catalogo","titulo":"Flash disponible"},{"type":"series","variant":"lista","bgColor":"#161412","eyebrow":"En qué trabajamos","titulo":"Estilos de la casa","items":[{"id":"estilo-blackwork","title":"Blackwork","hint":"Negro sólido, alto contraste","desc":"Trabajo en negro puro con masas sólidas y textura de punto. Ideal para piezas grandes que tienen que leerse de lejos y envejecer bien.","imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/5ba034e1-4935-4c3f-947c-f0238d9337df.jpg"},{"id":"estilo-fineline","title":"Fineline","hint":"Trazo fino, detalle mínimo","desc":"Líneas de una sola aguja para diseños delicados. Requiere piel en buen estado y un cuidado más estricto durante la cicatrización.","imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/f6672ce1-ada9-47fa-8486-9747463ded09.jpg"},{"id":"estilo-tradicional","title":"Tradicional","hint":"Old school, color plano","desc":"La escuela americana clásica: contorno grueso, paleta limitada y símbolos que ya probaron aguantar cien años.","imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/11075397-2c51-4adc-8ba3-70912ffbe70a.jpg"},{"id":"estilo-realismo","title":"Realismo","hint":"Retrato y sombra","desc":"Retratos y objetos con volumen real, trabajados en varias sesiones. Se cotiza por jornada y siempre arranca con boceto aprobado.","imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/118cb81b-4229-49f7-9b8c-894a27f084d3.jpg"}]},{"type":"equipo","variant":"retrato","titulo":"Los artistas"},{"type":"pasos","variant":"numerados","bgColor":"#161412","textColor":"#ece5d8","eyebrow":"Cómo funciona","titulo":"De la idea al turno","notaTitulo":"Seña de reserva: $25.000","notaTexto":"Se descuenta del total del trabajo. Si cancelás con menos de 48 hs de aviso, la seña no se devuelve.","botones":{"primary":{"label":"Reservar por WhatsApp →"}},"pasos":[{"id":"paso-1","titulo":"Contanos tu idea","desc":"Mandanos referencias, zona del cuerpo y tamaño aproximado por WhatsApp."},{"id":"paso-2","titulo":"Presupuesto y artista","desc":"Te decimos qué artista encaja mejor con el estilo y cuánto sale el trabajo."},{"id":"paso-3","titulo":"Seña y fecha","desc":"Con la seña abonada te reservamos el turno. El boceto se muestra el día de la sesión."},{"id":"paso-4","titulo":"La sesión","desc":"Vení comido, descansado y con ropa cómoda. Material descartable siempre a la vista."}]},{"type":"faq","variant":"lista","titulo":"Cuidados y recomendaciones"},{"type":"testimonios","variant":"scroll"},{"type":"contacto","variant":"mapa","titulo":"El estudio"},{"type":"footer","variant":"minimal"}]$sections$::jsonb,
  $demo${"nombreNegocio":"Tinta Negra","rubroLabel":"Estudio de tatuaje desde 2011","sobreNosotros":"","whatsapp":"5491166339812","telefono":"011 6633-9812","direccion":"Thames 1620, Palermo, CABA","horarios":"Mar a Sáb, 12 a 20 hs · Con turno previo","instagram":"@tintanegra.tattoo","galeria":["https://d38e2ri338t20n.cloudfront.net/uploads/9626e60b-65aa-4747-ab83-744867b5a3cf.jpg"]}$demo$::jsonb,
  $seeds${"productos":[{"id":"flash-1","nombre":"Serpiente y daga","precio":85000,"desc":"12 cm · Nico","disponible":true,"imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/849f932a-8dab-4d04-aa65-5c95e3dac42f.jpg"],"boton":{}},{"id":"flash-2","nombre":"Polilla nocturna","precio":62000,"desc":"9 cm · Vera","disponible":true,"imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/8d6fa581-38e6-4089-97b1-e63b398b8323.jpg"],"boton":{}},{"id":"flash-3","nombre":"Rosa tradicional","precio":95000,"desc":"14 cm · Nico","disponible":false,"imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/a54447d2-c916-454a-a179-b84c97152293.jpg"],"boton":{}},{"id":"flash-4","nombre":"Ojo de tormenta","precio":78000,"desc":"11 cm · Bruno","disponible":true,"imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/e8cf33af-ab1c-43a6-afc8-2a808bdec939.jpg"],"boton":{}},{"id":"flash-5","nombre":"Mano de fátima","precio":55000,"desc":"8 cm · Vera","disponible":false,"imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/84d50de0-9bff-4b7b-9301-6362981b4b44.jpg"],"boton":{}},{"id":"flash-6","nombre":"Calavera de ciervo","precio":120000,"desc":"16 cm · Bruno","disponible":true,"imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/68416774-527a-4e38-bfe4-d580fb586d74.jpg"],"boton":{}}],"equipo":[{"id":"artista-nico","nombre":"Nico Aguirre","rol":"Blackwork y tradicional","bio":"Fundó el estudio en 2011. Trabaja piezas grandes de espalda y brazo completo.","tags":["Blackwork","Tradicional","Cover-up"],"foto":"https://d38e2ri338t20n.cloudfront.net/uploads/49325f87-a30e-4578-b3b3-17cf1a091442.jpg"},{"id":"artista-vera","nombre":"Vera Ledesma","rol":"Fineline y botánico","bio":"Especialista en trazo fino y composiciones florales de tamaño chico y mediano.","tags":["Fineline","Botánico","Lettering"],"foto":"https://d38e2ri338t20n.cloudfront.net/uploads/4788d555-561f-4d80-910c-8d1a6e84e6db.jpg"},{"id":"artista-bruno","nombre":"Bruno Sanz","rol":"Realismo en negro y gris","bio":"Retratos y piezas de gran formato trabajadas en sesiones largas de jornada completa.","tags":["Realismo","Negro y gris","Retrato"],"foto":"https://d38e2ri338t20n.cloudfront.net/uploads/0383039b-e55f-492d-b244-86a28fc7dde6.jpg"}],"faqs":[{"id":"cuidado-1","q":"¿Qué hago antes de la sesión?","a":"Dormí bien, comé algo sustancioso una hora antes y evitá el alcohol las 24 horas previas. Vení con ropa que deje libre la zona a tatuar y no te expongas al sol esa semana."},{"id":"cuidado-2","q":"¿Cómo cuido el tatuaje los primeros días?","a":"Dejá el film las primeras 4 horas. Después lavá con agua tibia y jabón neutro dos veces por día, secá con toalla de papel y aplicá una capa muy fina de crema cicatrizante."},{"id":"cuidado-3","q":"¿Cuánto tarda en cicatrizar?","a":"La superficie cierra entre 10 y 14 días, pero la piel termina de asentarse recién al mes. Durante ese tiempo puede pelarse y picar: es normal, no rasques ni arranques las costras."},{"id":"cuidado-4","q":"¿Puedo ir a la pileta o al gimnasio?","a":"Nada de pileta, mar ni sauna durante tres semanas. Gimnasio suave a partir del cuarto día, evitando que la zona roce o transpire en exceso."},{"id":"cuidado-5","q":"¿El retoque tiene costo?","a":"El primer retoque dentro de los tres meses es sin cargo, siempre que hayas seguido los cuidados. Después de ese plazo se cotiza como sesión corta."}],"testimonios":[{"id":"testi-martina","nombre":"Martina R.","cargo":"Blackwork, brazo completo","texto":"Es mi tercer tatuaje con Nico y siempre la misma prolijidad. El estudio impecable y el trato de diez.","rating":5,"avatar":"","verificado":false},{"id":"testi-joaquin","nombre":"Joaquín D.","cargo":"Fineline, antebrazo","texto":"Vera entendió exactamente lo que quería con dos referencias. El fineline cicatrizó perfecto.","rating":5,"avatar":"","verificado":false},{"id":"testi-lucas","nombre":"Lucas P.","cargo":"Realismo, pierna","texto":"Bruno hizo el retrato de mi viejo y se me caían las lágrimas cuando lo vi terminado.","rating":5,"avatar":"","verificado":false},{"id":"testi-sofia","nombre":"Sofía M.","cargo":"Tradicional, tobillo","texto":"Me explicaron todos los cuidados por escrito y me escribieron a la semana para ver cómo iba.","rating":5,"avatar":"","verificado":false}]}$seeds$::jsonb,
